9| * KAN-938 `run-starters-from-frames`), written in the shorthand and parsed.
10| */
11|object CardioKinds {
12|    /** [activity]'s kinds in §9's order, Custom last. */
13|    fun kinds(activity: CardioActivity): List<CardioKind> = activity.kinds
14|
15|    /** The plan picking [kind] fills; Custom's is empty. */
16|    fun starter(
17|        activity: CardioActivity,
18|        kind: CardioKind,
19|    ): List<CardioStep> {
20|        val template = template(activity, kind)
21|        return when (val result = CardioShorthand.parse(template, activity, DistanceUnit.KM)) {
22|            is ShorthandResult.Plan -> result.steps
23|            is ShorthandError -> error("Starter template '$template' for $activity $kind does not parse: ${result.reason}")
24|        }
25|    }
26|
27|    private fun template(
28|        activity: CardioActivity,
29|        kind: CardioKind,
30|    ): String =
31|        when (activity) {
32|            CardioActivity.OUTDOOR_RUN, CardioActivity.TREADMILL_RUN -> run(activity, kind)
33|            CardioActivity.OUTDOOR_RIDE, CardioActivity.INDOOR_RIDE -> ride(kind)
34|            CardioActivity.ELLIPTICAL -> elliptical(kind)
35|            CardioActivity.ROWER -> rower(kind)
36|        }
37|
38|    private fun run(
39|        activity: CardioActivity,
40|        kind: CardioKind,
41|    ): String =
42|        when (kind) {
43|            CardioKind.EASY -> {
44|                "40min"
45|            }
46|
47|            CardioKind.RECOVERY -> {
48|                "25min"
49|            }
50|
51|            CardioKind.LONG -> {
52|                "90min"
53|            }
54|
55|            CardioKind.TEMPO -> {
56|                "15min wu, 20min, 10min cd"
57|            }
58|
59|            CardioKind.INTERVALS -> {
60|                "10min wu, 6x(800m @4:00-4:10, 2min jog), 10min cd"
61|            }
62|
63|            CardioKind.FARTLEK -> {
64|                "10min wu, 8x(1min \"hard\", 1min \"easy\"), 10min cd"
65|            }
66|
67|            CardioKind.HILLS -> {
68|                if (activity == CardioActivity.OUTDOOR_RUN) {
69|                    "10min wu, 8x(60s \"uphill\", 90s jog \"jog down\"), 10min cd"
70|                } else {
71|                    "10min wu, 8x(60s @inc6, 90s rec @inc1), 10min cd"
72|                }
73|            }
74|
75|            CardioKind.PROGRESSION -> {
76|                "3x(15min) \"each faster\""
77|            }
78|
79|            CardioKind.RACE -> {
80|                "15min wu, open \"race distance\", open"
81|            }
82|
83|            else -> {
84|                ""
85|            }
86|        }
87|
88|    private fun ride(kind: CardioKind): String =
89|        when (kind) {
90|            CardioKind.ENDURANCE -> "90min"
91|            CardioKind.RECOVERY -> "45min"
92|            CardioKind.TEMPO -> "15min wu, 2x(20min, 5min rec), 10min cd"
93|            CardioKind.SWEET_SPOT -> "15min wu, 3x(12min, 5min rec), 10min cd"
94|            CardioKind.THRESHOLD -> "15min wu, 2x(20min, 10min rec), 10min cd"
95|            CardioKind.VO2_MAX -> "15min wu, 5x(3min, 3min rec), 10min cd"
96|            CardioKind.SPRINTS -> "15min wu, 8x(20s, 2:40 rec), 10min cd"
97|            CardioKind.CLIMBS -> "15min wu, 4x(8min \"climb\", 4min rec), 10min cd"
98|            CardioKind.CADENCE_DRILLS -> "10min wu, 6x(2min @100rpm, 2min rec), 10min cd"
99|            else -> ""
100|        }
101|
