105|            CardioKind.INTERVALS -> "5min wu, 8x(1min, 1min rec), 5min cd"
106|            CardioKind.HILLS -> "5min wu, 6x(2min @r12, 2min rec @r6), 5min cd"
107|            else -> ""
108|        }
109|
110|    private fun rower(kind: CardioKind): String =
111|        when (kind) {
112|            CardioKind.STEADY_STATE -> "30min"
113|            CardioKind.INTERVALS -> "10min wu, 8x(500m, 2min rest), 5min cd"
114|            CardioKind.PYRAMID -> "10min wu, 1min, 1min rest, 2min, 2min rest, 3min, 3min rest, 2min, 2min rest, 1min, 5min cd"
115|            CardioKind.SPRINTS -> "10min wu, 10x(30s, 90s rest), 5min cd"
116|            CardioKind.TEST_2K -> "10min wu, 2000m \"test\", 5min cd"
117|            else -> ""
118|        }
