// This Kotlin/Compose Multiplatform version bump (Kotlin 2.1.20 -> 2.4.10, Compose 1.8.2 -> 1.11.1,
// AGP 8.13.2 -> 9.3.1) was verified to *compile* for both iOS targets below (iosX64 was dropped —
// Compose Multiplatform 1.11.x publishes no stable runtime-iosx64 artifact), but iOS *test
// execution* could not be verified on the machine that made this change — it has only the Xcode
// Command Line Tools, not a full Xcode install. Flagged for CI or a full-Xcode machine to confirm
// the iOS test suite still runs green before this ships.

plugins {
    kotlin("multiplatform")
    kotlin("plugin.compose")
    kotlin("plugin.serialization") version "2.4.10"
    id("org.jetbrains.compose")
    id("com.android.library")
}

kotlin {
    androidTarget {
        compilerOptions {
            jvmTarget.set(org.jetbrains.kotlin.gradle.dsl.JvmTarget.JVM_17)
        }
    }
    jvm("desktop")
    @OptIn(org.jetbrains.kotlin.gradle.ExperimentalWasmDsl::class)
    wasmJs {
        browser()
    }
    // No iosX64: Compose Multiplatform stopped publishing stable artifacts for the Intel iOS
    // simulator target in the 1.11 line (the newest `runtime-iosx64` on Maven Central is
    // 1.11.0-alpha01). iosArm64 covers real devices and iosSimulatorArm64 covers the simulator
    // on Apple Silicon Macs, which is what the supported toolchain runs.
    listOf(
        iosArm64(),
        iosSimulatorArm64(),
    ).forEach { target ->
        target.binaries.framework {
            baseName = "Shared"
            isStatic = true
        }
    }

    sourceSets {
        commonMain.dependencies {
            implementation(compose.runtime)
            implementation(compose.foundation)
            implementation(compose.material3)
            implementation(compose.materialIconsExtended)
            implementation(compose.ui)
            implementation(compose.components.resources)
            implementation("io.ktor:ktor-client-core:3.5.2")
            implementation("io.ktor:ktor-client-content-negotiation:3.5.2")
            implementation("io.ktor:ktor-serialization-kotlinx-json:3.5.2")
            implementation("org.jetbrains.kotlinx:kotlinx-serialization-json:1.11.0")
            implementation("org.jetbrains.androidx.navigation:navigation-compose:2.9.2")
            // navigation-compose 2.9.2 does not bring navigationevent in transitively (checked on
            // desktopCompileClasspath), and the shell's root system-back handler needs it.
            implementation("org.jetbrains.androidx.navigationevent:navigationevent-compose:1.1.0")
            implementation("org.jetbrains.kotlinx:kotlinx-coroutines-core:1.11.0")
            // api: LocalDate/Instant appear on shared public UI/API surfaces (e.g. GymieApp).
            api("org.jetbrains.kotlinx:kotlinx-datetime:0.8.0")
            implementation("io.coil-kt.coil3:coil-compose:3.5.0")
            implementation("io.coil-kt.coil3:coil-network-ktor3:3.5.0")
        }
        androidMain.dependencies {
            implementation("io.ktor:ktor-client-okhttp:3.5.2")
        }
        val desktopMain by getting {
            dependencies {
                implementation("io.ktor:ktor-client-cio:3.5.2")
            }
        }
        val iosArm64Main by getting
        val iosSimulatorArm64Main by getting
        val iosMain by creating {
            dependsOn(commonMain.get())
            iosArm64Main.dependsOn(this)
            iosSimulatorArm64Main.dependsOn(this)
            dependencies {
                implementation("io.ktor:ktor-client-darwin:3.5.2")
            }
        }
        wasmJsMain.dependencies {
            implementation("io.ktor:ktor-client-js:3.5.2")
            implementation("org.jetbrains.kotlinx:kotlinx-browser:0.5.0")
        }
        commonTest.dependencies {
            implementation(kotlin("test"))
            implementation("org.jetbrains.kotlinx:kotlinx-coroutines-test:1.11.0")
            implementation("io.ktor:ktor-client-mock:3.5.2")
        }
        val desktopTest by getting {
            dependsOn(commonTest.get())
            dependencies {
                implementation(compose.uiTest)
                implementation(compose.desktop.currentOs)
            }
        }
    }

    compilerOptions {
        freeCompilerArgs.add("-Xexpect-actual-classes")
    }
}

